#include <stdio.h>

void printAll(int arr[], int length) {
    for (int i = 0; i < length; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");
}

int main() {
    int numbers[] = {10, 20, 30};
    int length = sizeof(numbers) / sizeof(numbers[0]);   // valid HERE, before decay
    printAll(numbers, length);

    int grid[2][3] = {{1, 2, 3}, {4, 5, 6}};
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 3; j++) {
            printf("%d ", grid[i][j]);
        }
    }
    printf("\n");
    return 0;
}
